#!/usr/bin/env node

/**
 * Vibes-Plug Speculative Multi-Draft Consensus Synthesizer (2026 Sovereign Edition)
 * 
 * Implements the Speculative Multi-Draft Synthesizer & Multi-Model Consensus Architecture.
 * Analyzes competing code drafts generated by parallel swarm subagents or different frontier models,
 * scores them across 5 orthogonal vectors (Anti-Slop, Error Resilience, Cyclomatic Simplicity,
 * Type Safety, and Micro-Sandbox Performance), and arbitrates the optimal consensus solution.
 * 
 * Features:
 * - Multi-draft parallel ingestion from files, strings, or stdin JSON
 * - Anti-Slop Directive verification (Pillar 1 to 7) via Critic-Validator
 * - Cyclomatic complexity & guard clause structural analysis
 * - Ephemeral WASM/VM sandbox execution benchmark (latency & fuzz resilience)
 * - Multi-dimensional radar scoring matrix & candidate ranking
 * - Automated consensus synthesis & Frontier Arbiter prompt compilation
 * - Zero external dependencies (pure Node.js built-ins)
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { criticValidate } from './critic-validator.mjs';
import { executeInSandbox } from './wasm-sandbox.mjs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const PLUGIN_ROOT = path.resolve(__dirname, '..');

/**
 * @typedef {Object} CandidateDraftInput
 * @property {string} [id]
 * @property {string} [name]
 * @property {string} [path]
 * @property {string} code
 * @property {string} [model]
 * @property {string} [author]
 * @property {string} [rationale]
 */

/**
 * Calculate Cyclomatic Complexity approximation from code
 * @param {string} code
 * @returns {number}
 */
export function calculateCyclomaticComplexity(code) {
  if (!code || typeof code !== 'string') return 1;

  // Remove string literals and comments to prevent false branch hits
  const clean = code
    .replace(/\/\*[\s\S]*?\*\/|\/\/.*/g, '')
    .replace(/(["'`])(?:(?=(\\?))\2[\s\S])*?\1/g, '""');

  let complexity = 1;
  const branchPatterns = [
    /\bif\s*\(/g,
    /\belse\s+if\s*\(/g,
    /\bfor\s*\(/g,
    /\bwhile\s*\(/g,
    /\bcase\s+[^:]+:/g,
    /\bcatch\s*\(/g,
    /\s*\?\s*[^:]+\s*:/g, // ternary
    /&&/g,
    /\|\|/g
  ];

  for (const pattern of branchPatterns) {
    const matches = clean.match(pattern);
    if (matches) {
      complexity += matches.length;
    }
  }

  return complexity;
}

/**
 * Analyze Error Resilience & Defensive Boundaries
 * @param {string} code
 * @returns {Object}
 */
export function analyzeResilience(code) {
  if (!code) return { score: 50, metrics: {} };

  const hasTryCatch = /try\s*\{[\s\S]*?\}\s*catch/g.test(code);
  const catchCount = (code.match(/catch\s*\(/g) || []).length;
  const throwCount = (code.match(/\bthrow\s+new\s+\w*Error/g) || []).length;
  const earlyReturnGuards = (code.match(/if\s*\([^)]+\)\s*(?:return|throw)\b/g) || []).length;
  const inputValidationCount = (code.match(/(?:typeof|Array\.isArray|isNaN|Number\.isFinite|instanceof|=== null|=== undefined|!== null|!== undefined)/g) || []).length;

  let score = 50;
  if (hasTryCatch) score += 15;
  score += Math.min(20, earlyReturnGuards * 5);
  score += Math.min(15, inputValidationCount * 3);
  if (throwCount > 0) score += 10;

  // Penalize silent empty catches
  if (/catch\s*\([^)]*\)\s*\{\s*\}/.test(code)) {
    score -= 30;
  }

  score = Math.max(10, Math.min(100, score));

  return {
    score,
    metrics: {
      hasTryCatch,
      catchCount,
      throwCount,
      earlyReturnGuards,
      inputValidationCount
    }
  };
}

/**
 * Analyze Type Safety & Contract Rigor
 * @param {string} code
 * @returns {Object}
 */
export function analyzeTypeSafety(code) {
  if (!code) return { score: 50, metrics: {} };

  const hasInterfaces = (code.match(/\binterface\s+[A-Z]\w*/g) || []).length;
  const hasTypeAliases = (code.match(/\btype\s+[A-Z]\w*\s*=/g) || []).length;
  const hasTypedParams = (code.match(/:\s*(?:string|number|boolean|Record|Array|Promise<|void|[A-Z]\w*)/g) || []).length;
  const hasAnyUsage = (code.match(/:\s*any\b|as\s+any\b/g) || []).length;
  const hasJSDoc = (code.match(/\/\*\*[\s\S]*?\*\//g) || []).length;

  let score = 50;
  if (hasInterfaces > 0 || hasTypeAliases > 0) score += 20;
  score += Math.min(25, hasTypedParams * 3);
  if (hasJSDoc > 0) score += 10;
  if (hasAnyUsage > 0) {
    score -= hasAnyUsage * 10;
  }

  score = Math.max(10, Math.min(100, score));

  return {
    score,
    metrics: {
      hasInterfaces,
      hasTypeAliases,
      hasTypedParams,
      hasAnyUsage,
      hasJSDoc
    }
  };
}

/**
 * Deep Analysis of a Single Candidate Draft
 * @param {CandidateDraftInput} draft
 * @param {Object} [options]
 * @returns {Promise<Object>}
 */
export async function analyzeCandidateDraft(draft, options = {}) {
  const code = String(draft.code || '');
  const id = draft.id || draft.name || 'draft-' + Math.random().toString(36).slice(2, 7);
  const model = draft.model || 'unknown-model';
  const author = draft.author || 'subagent-worker';
  const rationale = draft.rationale || 'Candidate implementation proposal';

  // 1. Critic-Validator Analysis (Anti-Slop & UI Contract)
  const criticReport = criticValidate(code, {
    language: options.language || 'typescript',
    strictness: 'strict'
  });

  // 2. Cyclomatic Complexity & Code Metrics
  const cyclomaticComplexity = calculateCyclomaticComplexity(code);
  const linesCount = code.split('\n').length;
  const charCount = code.length;

  // Higher score for reasonable cyclomatic complexity (1-10 is great, >20 degrades score)
  let complexityScore = 100;
  if (cyclomaticComplexity > 25) {
    complexityScore = Math.max(30, 100 - (cyclomaticComplexity - 25) * 3);
  } else if (cyclomaticComplexity > 12) {
    complexityScore = Math.max(65, 100 - (cyclomaticComplexity - 12) * 2);
  }

  // 3. Resilience & Defensive Boundaries
  const resilienceAnalysis = analyzeResilience(code);

  // 4. Type Safety & Contract Rigor
  const typeAnalysis = analyzeTypeSafety(code);

  // 5. Micro-Sandbox Execution Benchmark (Optional / if --verify)
  let sandboxBenchmark = { executed: false, passed: true, latencyMs: 0 };
  if (options.verify) {
    try {
      const sandboxRes = await executeInSandbox(code, { timeoutMs: 500 });
      sandboxBenchmark = {
        executed: true,
        passed: sandboxRes.success,
        latencyMs: sandboxRes.executionTimeMs,
        error: sandboxRes.error || null
      };
    } catch (err) {
      sandboxBenchmark = {
        executed: true,
        passed: false,
        latencyMs: 0,
        error: err.message
      };
    }
  }

  // 6. Multi-Vector Radar Scoring Calculation
  // Weights:
  // - Anti-Slop / Critic Score: 30%
  // - Error Resilience: 25%
  // - Algorithmic Complexity / Simplicity: 20%
  // - Type Safety: 15%
  // - Sandbox Benchmark: 10%
  let perfScore = 100;
  if (sandboxBenchmark.executed) {
    if (!sandboxBenchmark.passed) {
      perfScore = 20;
    } else if (sandboxBenchmark.latencyMs > 50) {
      perfScore = Math.max(50, 100 - (sandboxBenchmark.latencyMs - 50));
    }
  }

  const weightedTotal = (
    criticReport.score * 0.30 +
    resilienceAnalysis.score * 0.25 +
    complexityScore * 0.20 +
    typeAnalysis.score * 0.15 +
    perfScore * 0.10
  );

  const finalScore = parseFloat(weightedTotal.toFixed(1));

  return {
    id,
    name: draft.name || id,
    path: draft.path || null,
    model,
    author,
    rationale,
    code,
    metrics: {
      linesCount,
      charCount,
      cyclomaticComplexity,
      violationsCount: criticReport.violations.length,
      antiSlopScore: criticReport.score,
      resilienceScore: resilienceAnalysis.score,
      complexityScore,
      typeSafetyScore: typeAnalysis.score,
      perfScore,
      finalScore
    },
    resilienceDetails: resilienceAnalysis.metrics,
    typeSafetyDetails: typeAnalysis.metrics,
    sandboxBenchmark,
    violations: criticReport.violations,
    suggestions: criticReport.suggestions
  };
}

/**
 * Reconcile Multiple Speculative Drafts & Synthesize Consensus
 * @param {Array<CandidateDraftInput>} drafts
 * @param {Object} [options]
 * @returns {Promise<Object>}
 */
export async function reconcileSpeculativeDrafts(drafts, options = {}) {
  if (!Array.isArray(drafts) || drafts.length === 0) {
    throw new Error('At least one candidate draft is required for speculative reconciliation.');
  }

  const spec = options.spec || 'Optimal, production-ready implementation adhering to Anti-Slop gold standards.';

  // Deep analyze each candidate draft
  const analyzedDrafts = [];
  for (const draft of drafts) {
    const analysis = await analyzeCandidateDraft(draft, options);
    analyzedDrafts.push(analysis);
  }

  // Rank drafts by finalScore descending
  analyzedDrafts.sort((a, b) => b.metrics.finalScore - a.metrics.finalScore);

  const winner = analyzedDrafts[0];

  // Identify vector champions
  let bestAlgorithm = analyzedDrafts[0];
  let bestResilience = analyzedDrafts[0];
  let bestTyping = analyzedDrafts[0];

  for (const d of analyzedDrafts) {
    if (d.metrics.complexityScore > bestAlgorithm.metrics.complexityScore) {
      bestAlgorithm = d;
    }
    if (d.metrics.resilienceScore > bestResilience.metrics.resilienceScore) {
      bestResilience = d;
    }
    if (d.metrics.typeSafetyScore > bestTyping.metrics.typeSafetyScore) {
      bestTyping = d;
    }
  }

  // Generate Consensus Synthesis Rationale
  const synthesisNotes = [];
  synthesisNotes.push(`Primary winner: [${winner.id}] (Model: ${winner.model}) with overall score ${winner.metrics.finalScore}/100.`);

  if (bestAlgorithm.id !== winner.id) {
    synthesisNotes.push(`Algorithm note: [${bestAlgorithm.id}] exhibited superior cyclomatic simplicity (${bestAlgorithm.metrics.cyclomaticComplexity} branches).`);
  }
  if (bestResilience.id !== winner.id) {
    synthesisNotes.push(`Resilience note: [${bestResilience.id}] featured higher defensive guard density.`);
  }
  if (bestTyping.id !== winner.id) {
    synthesisNotes.push(`Type safety note: [${bestTyping.id}] demonstrated stricter TypeScript interfaces.`);
  }

  // Compile Frontier Arbiter Prompt for LLM Swarms
  const arbiterPrompt = [
    'You are the Master Frontier Arbiter in an autonomous AI swarm.',
    'Your task is to analyze the following candidate code drafts for the given specification, identify their individual strengths, and synthesize a single, flawless, production-ready implementation.',
    '',
    'SPECIFICATION:',
    spec,
    '',
    'CANDIDATE DRAFTS:',
    analyzedDrafts.map((d, idx) => (
      `### DRAFT ${idx + 1} (${d.id} | Model: ${d.model}):\n` +
      `Rationale: ${d.rationale}\n` +
      `Score: ${d.metrics.finalScore}/100 | Complexity: ${d.metrics.cyclomaticComplexity} | Resilience: ${d.metrics.resilienceScore}\n\n` +
      `\`\`\`typescript\n${d.code}\n\`\`\``
    )).join('\n\n---\n\n'),
    '',
    'SYNTHESIS MANDATES:',
    `1. Primary base architecture: Adopt the structural integrity of Draft 1 [${winner.id}].`,
    `2. Algorithmic core: Ensure optimal execution performance (reference ${bestAlgorithm.id}).`,
    `3. Error boundaries: Enforce robust guard clauses and typed error handling (reference ${bestResilience.id}).`,
    `4. Type contracts: Strictly define all interfaces without "any" (reference ${bestTyping.id}).`,
    '5. Anti-Slop Directive: Output 100% complete, working code with zero ellipses, zero TODOs, and crisp logic.'
  ].join('\n');

  // Synthesized Code Selection
  // In automated mode, the winning candidate serves as the synthesized code base,
  // supplemented with consensus metadata header.
  const synthesizedHeader = [
    '/**',
    ' * @file Synthesized Consensus Implementation',
    ` * @arbiter Vibes-Plug Speculative Multi-Draft Consensus Synthesizer`,
    ` * @score ${winner.metrics.finalScore}/100 [Consensus Winner: ${winner.id}]`,
    ` * @model ${winner.model}`,
    ` * @vector-champions Algorithm: ${bestAlgorithm.id} | Resilience: ${bestResilience.id} | Types: ${bestTyping.id}`,
    ' */\n'
  ].join('\n');

  const synthesizedCode = synthesizedHeader + winner.code;

  return {
    spec,
    totalDrafts: analyzedDrafts.length,
    winner: {
      id: winner.id,
      name: winner.name,
      model: winner.model,
      score: winner.metrics.finalScore,
      path: winner.path
    },
    champions: {
      overall: winner.id,
      algorithm: bestAlgorithm.id,
      resilience: bestResilience.id,
      typeSafety: bestTyping.id
    },
    synthesisNotes,
    rankedDrafts: analyzedDrafts,
    synthesizedCode,
    arbiterPrompt
  };
}

/**
 * Format Consensus Report as Rich Terminal Output
 * @param {Object} result
 * @returns {string}
 */
export function formatConsensusReport(result) {
  const lines = [];

  lines.push('\n╔═══════════════════════════════════════════════════════════════════════════════════════════════╗');
  lines.push('║        🧬 VIBES-PLUG SPECULATIVE MULTI-DRAFT CONSENSUS ARBITER (2026 SOVEREIGN)               ║');
  lines.push('╚═══════════════════════════════════════════════════════════════════════════════════════════════╝\n');

  lines.push(`  🎯 Specification : ${result.spec}`);
  lines.push(`  🏆 Consensus Winner : [${result.winner.id}] (Model: ${result.winner.model}) — Score: ${result.winner.score}/100`);
  lines.push(`  📊 Evaluated Drafts : ${result.totalDrafts} candidate implementations\n`);

  lines.push('┌───────────────────────────────────────────────────────────────────────────────────────────────┐');
  lines.push('│ 🏅 MULTI-DRAFT ARBITRATION MATRIX & RADAR SCORING                                             │');
  lines.push('├──────────────────┬─────────────────┬──────────┬──────────┬──────────┬──────────┬──────────────┤');
  lines.push('│ DRAFT ID         │ MODEL           │ OVERALL  │ ANTI-SLOP│ RESIL.   │ COMPLEX. │ TYPE SAFETY  │');
  lines.push('├──────────────────┼─────────────────┼──────────┼──────────┼──────────┼──────────┼──────────────┤');

  for (const d of result.rankedDrafts) {
    const isWinner = d.id === result.winner.id;
    const marker = isWinner ? '★ ' : '  ';
    const idStr = (marker + d.id).padEnd(16).slice(0, 16);
    const modelStr = d.model.padEnd(15).slice(0, 15);
    const overallStr = `${d.metrics.finalScore}`.padStart(6) + '  ';
    const slopStr = `${d.metrics.antiSlopScore}`.padStart(6) + '  ';
    const resStr = `${d.metrics.resilienceScore}`.padStart(6) + '  ';
    const compStr = `${d.metrics.complexityScore}`.padStart(6) + '  ';
    const typeStr = `${d.metrics.typeSafetyScore}`.padStart(6) + '      ';

    lines.push(`│ ${idStr} │ ${modelStr} │ ${overallStr}│ ${slopStr}│ ${resStr}│ ${compStr}│ ${typeStr}│`);
  }
  lines.push('└──────────────────┴─────────────────┴──────────┴──────────┴──────────┴──────────┴──────────────┘\n');

  lines.push('┌───────────────────────────────────────────────────────────────────────────────────────────────┐');
  lines.push('│ 🔬 CONSENSUS ARBITRATION VECTOR CHAMPIONS                                                     │');
  lines.push('├───────────────────────────────────────────────────────────────────────────────────────────────┤');
  lines.push(`│   • Best Overall Synthesis : [${result.champions.overall}]`.padEnd(96) + '│');
  lines.push(`│   • Optimal Algorithm      : [${result.champions.algorithm}]`.padEnd(96) + '│');
  lines.push(`│   • Highest Error Boundary : [${result.champions.resilience}]`.padEnd(96) + '│');
  lines.push(`│   • Superior Type Safety   : [${result.champions.typeSafety}]`.padEnd(96) + '│');
  lines.push('└───────────────────────────────────────────────────────────────────────────────────────────────┘\n');

  lines.push('┌───────────────────────────────────────────────────────────────────────────────────────────────┐');
  lines.push('│ 📝 ARBITER SYNTHESIS NOTES                                                                    │');
  lines.push('├───────────────────────────────────────────────────────────────────────────────────────────────┤');
  for (const note of result.synthesisNotes) {
    lines.push(`│   ℹ️  ${note}`.padEnd(96) + '│');
  }
  lines.push('└───────────────────────────────────────────────────────────────────────────────────────────────┘\n');

  return lines.join('\n');
}

/**
 * Load draft files from disk
 * @param {Array<string>} filePaths
 * @returns {Promise<Array<CandidateDraftInput>>}
 */
export async function loadDraftsFromFiles(filePaths) {
  const drafts = [];

  for (let i = 0; i < filePaths.length; i++) {
    const filePath = path.resolve(filePaths[i]);
    const code = await fs.readFile(filePath, 'utf-8');
    const baseName = path.basename(filePath);

    // Extract potential model / author hints from comments
    let model = 'candidate-' + (i + 1);
    const modelMatch = code.match(/@model\s+([^\n\r]+)/i);
    if (modelMatch) {
      model = modelMatch[1].trim();
    }

    let rationale = `Candidate draft loaded from ${baseName}`;
    const rationaleMatch = code.match(/@rationale\s+([^\n\r]+)/i);
    if (rationaleMatch) {
      rationale = rationaleMatch[1].trim();
    }

    drafts.push({
      id: baseName,
      name: baseName,
      path: filePath,
      code,
      model,
      rationale
    });
  }

  return drafts;
}

/**
 * CLI Runner for vibes consensus
 */
export async function runConsensusCli() {
  const args = process.argv.slice(2);
  const isJson = args.includes('--json');
  const isVerify = args.includes('--verify');

  let spec = 'Optimal, production-ready implementation adhering to Anti-Slop gold standards.';
  const specIdx = args.indexOf('--spec');
  if (specIdx !== -1 && args[specIdx + 1]) {
    spec = args[specIdx + 1];
  }

  let outputPath = null;
  const outIdx = args.indexOf('--output');
  if (outIdx !== -1 && args[outIdx + 1]) {
    outputPath = args[outIdx + 1];
  }

  // Filter out flag options to collect file paths
  const filePaths = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--spec' || arg === '--output') {
      i++; // skip next value
      continue;
    }
    if (!arg.startsWith('--')) {
      filePaths.push(arg);
    }
  }

  let drafts = [];

  if (filePaths.length > 0) {
    try {
      drafts = await loadDraftsFromFiles(filePaths);
    } catch (err) {
      console.error(`❌ Error reading draft files: ${err.message}`);
      process.exit(1);
    }
  } else if (args.includes('--stdin')) {
    // Read from stdin when explicitly requested
    try {
      const stdinChunks = [];
      for await (const chunk of process.stdin) {
        stdinChunks.push(chunk);
      }
      const stdinText = Buffer.concat(stdinChunks).toString('utf-8').trim();
      if (stdinText) {
        const parsed = JSON.parse(stdinText);
        if (Array.isArray(parsed)) {
          drafts = parsed;
        } else if (parsed.drafts && Array.isArray(parsed.drafts)) {
          drafts = parsed.drafts;
          if (parsed.spec) spec = parsed.spec;
        }
      }
    } catch (err) {
      console.error(`❌ Error parsing JSON from stdin: ${err.message}`);
      process.exit(1);
    }
  }

  if (drafts.length === 0) {
    console.log(`
🌊 Vibes-Plug Speculative Multi-Draft Consensus Synthesizer

Usage:
  vibes consensus <file1> <file2> [file3...] [options]
  cat drafts.json | vibes consensus --json

Options:
  --spec <text>      Target problem specification
  --verify           Run ephemeral micro-sandbox benchmark & fuzz check
  --output <file>    Save synthesized consensus code to file
  --json             Output arbitration matrix in structured JSON format
`);
    process.exit(0);
  }

  try {
    const result = await reconcileSpeculativeDrafts(drafts, {
      spec,
      verify: isVerify
    });

    if (outputPath) {
      const resolvedOut = path.resolve(outputPath);
      await fs.mkdir(path.dirname(resolvedOut), { recursive: true });
      await fs.writeFile(resolvedOut, result.synthesizedCode, 'utf-8');
    }

    if (isJson) {
      console.log(JSON.stringify(result, null, 2));
    } else {
      console.log(formatConsensusReport(result));
      if (outputPath) {
        console.log(`💾 Synthesized consensus code written to: ${outputPath}\n`);
      }
    }
  } catch (err) {
    console.error(`❌ Speculative consensus failed: ${err.message}`);
    process.exit(1);
  }
}

// Direct execution check
const isDirectExecution = process.argv[1] && (
  path.resolve(process.argv[1]).toLowerCase() === path.resolve(__filename).toLowerCase() ||
  process.argv[1].endsWith('speculative-consensus.mjs')
);

if (isDirectExecution) {
  runConsensusCli();
}
